mapper.select:
select
*
from
wms_party_a_borrow
where
bool_delete_enum = 0

    and basic_class = #{basicClass}


    and project_id = #{projectId}


    and borrow_project_id = #{borrowProjectId}


    and return_status = #{returnStatus}


    and borrow_transfer_id in ((select id from wms_transfer where bool_delete_enum = 0 and serial_number like CONCAT('%', #{transferSN},'%') ) )


    
        and transfer_time > #{transferTime[0]}
    
    
        and transfer_time < #{transferTime[1]}
    


    and transfer_name like CONCAT('%', #{operatorName},'%')
